<?php
$u=rtrim($_ENV['APP_URL']??'','/');
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$canRequest=\App\Services\AccessService::can('academico.matriculas.gestionar');
?>
<div class="page-head"><div><span class="eyebrow">ACADÉMICO · GESTIÓN DE CUPOS</span><h1>Control de cupos</h1><p>Consulta la ocupación de secciones y solicita ampliaciones a Coordinación TICs.</p></div></div>
<?php if($flash):?><section class="card"><p><?=$h($flash['message']??'')?></p></section><?php endif;?>
<section class="card"><form method="get" action="<?=$u?>/admin/academico/cupos" style="display:flex;flex-wrap:wrap;gap:1rem;align-items:end"><label>Período académico<select name="periodo"><?php foreach($periods as $p):?><option value="<?=(int)$p['id']?>" <?=(int)$p['id']===$period?'selected':''?>><?=$h($p['nombre'])?></option><?php endforeach;?></select></label><label>Buscar sección, código u oferta<input name="buscar" value="<?=$h($search)?>" placeholder="Ej. Administración"></label><button class="btn">Filtrar</button></form></section>
<section class="card"><h2>Ocupación institucional por cohorte</h2>
<p>Estudiantes únicos por oferta académica (período, carrera, sede y modalidad), nivel y paralelo. Un estudiante con varias asignaturas del mismo nivel se cuenta una sola vez. Se excluyen las matrículas anuladas y los borradores.</p>
<div class="table-scroll"><table><thead><tr><th>Carrera / Oferta</th><th>Nivel</th><th>Paralelo</th><th>Estudiantes únicos</th><th>Cupo de referencia</th><th>Disponibles</th><th>Observaciones</th><th>Ampliación</th></tr></thead><tbody>
<?php foreach(($cohorts??[]) as $c):
$used=(int)$c['estudiantes_unicos'];
$minimum=$c['cupo_minimo']===null?null:(int)$c['cupo_minimo'];
$maximum=$c['cupo_maximo']===null?null:(int)$c['cupo_maximo'];
$unequal=$minimum!==$maximum;
$limit=$minimum;
$full=$limit!==null&&$used>=$limit;$pendingCohort=(int)($c['solicitudes_cohorte_pendientes']??0)>0;
?>
<tr><td><strong><?=$h($c['carrera_nombre'])?></strong><div><?=$h($c['oferta_nombre'])?></div></td><td><?=$h($c['nivel_nombre'])?></td><td><?=$h($c['paralelo']??'Sin paralelo')?></td><td><?=$used?></td><td><?=$limit===null?'Sin configurar':$limit?></td><td><?=$limit===null?'—':max(0,$limit-$used)?></td><td><?php if($unequal):?>Cupos diferentes entre asignaturas; revisar configuración. <?php endif;?><?php if((int)$c['solicitudes_pendientes']>0):?>Solicitud pendiente en TICs. <?php endif;?><?=$full?'Cupo de referencia alcanzado':'Disponible'?></td><td><?php if($pendingCohort):?>Pendiente TICs<?php elseif($full&&$canRequest&&$limit!==null&&!$unequal&&$c['paralelo']==='A'):?><button type="button" class="btn" data-cohort-request data-offer="<?=(int)$c['oferta_id']?>" data-level="<?=(int)$c['nivel_id']?>" data-parallel="<?=(int)$c['paralelo_id']?>" data-name="<?=$h($c['carrera_nombre'].' · '.$c['nivel_nombre'].' · Paralelo A')?>">Solicitar ampliación</button><?php elseif($unequal):?>Conciliar cupos<?php else:?>—<?php endif;?></td></tr>
<?php endforeach;?>
<?php if(empty($cohorts)):?><tr><td colspan="8">No hay cohortes para este período.</td></tr><?php endif;?></tbody></table></div>
<p><strong>Importante:</strong> esta es una vista de conciliación. Si existen cupos diferentes entre asignaturas se usa el menor como referencia conservadora. Las solicitudes de cohorte requieren aprobación TICs. El bloqueo global transaccional de matrículas se implementará en una fase posterior.</p></section>
<section class="card"><h2>Detalle por asignatura / sección</h2><p>Conteo por asignatura para conciliación con la ocupación institucional de la tabla superior.</p><div class="table-scroll"><table><thead><tr><th>Oferta / Sección</th><th>Paralelo</th><th>Ocupación</th><th>Disponibles</th><th>Estado</th><th>Solicitud</th></tr></thead><tbody>
<?php foreach($sections as $s):$max=$s['cupo_maximo']===null?null:(int)$s['cupo_maximo'];$used=(int)$s['ocupados'];$full=$max!==null&&$used>=$max;$pending=(int)$s['pendientes']>0;?><tr><td><strong><?=$h($s['oferta_nombre'])?></strong><div><?=$h($s['codigo'])?> · <?=$h($s['nombre'])?> · #<?=(int)$s['id']?></div></td><td><?=$h($s['paralelo']??'Sin paralelo')?></td><td><?=$used?> / <?=$max===null?'Sin límite':$max?></td><td><?=$max===null?'—':max(0,$max-$used)?></td><td><?=$pending?'Solicitud pendiente':($full?'Cupo completo':'Disponible')?></td><td><?php if($pending):?>En revisión por TICs<?php elseif($full&&$canRequest):?><button class="btn" type="button" data-request-section="<?=(int)$s['id']?>" data-request-label="<?=$h($s['codigo'])?>">Solicitar ampliación</button><?php elseif($full):?>Requiere permiso de gestión<?php else:?>—<?php endif;?></td></tr><?php endforeach;?>
<?php if(!$sections):?><tr><td colspan="6">No hay secciones para estos filtros.</td></tr><?php endif;?></tbody></table></div></section>
<div id="capacityRequestModal" hidden style="position:fixed;inset:0;background:#0009;z-index:9999;display:none;align-items:center;justify-content:center;padding:1rem" role="dialog" aria-modal="true" aria-labelledby="capacityModalTitle"><div class="card" style="width:min(100%,540px);max-height:90vh;overflow:auto"><h2 id="capacityModalTitle">Solicitar ampliación de cupos</h2><p id="capacityModalSection"></p><p>La solicitud quedará pendiente de aprobación de Coordinación TICs.</p><form method="post" action="<?=$u?>/admin/academico/cupos/solicitar"><input type="hidden" name="_csrf" value="<?=$h(\App\Core\Csrf::token())?>"><input type="hidden" name="seccion_id" id="capacitySectionId"><label>Cupos adicionales<input type="number" name="cantidad" min="1" max="100" required></label><label>Justificación<textarea name="motivo" minlength="10" required></textarea></label><div style="display:flex;gap:.75rem;flex-wrap:wrap"><button class="btn" type="button" id="capacityCancel">Cancelar</button><button class="btn" type="submit">Enviar solicitud</button></div></form></div></div>
<script>(function(){const m=document.getElementById('capacityRequestModal');const close=()=>{m.hidden=true;m.style.display='none'};document.querySelectorAll('[data-request-section]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('capacitySectionId').value=b.dataset.requestSection;document.getElementById('capacityModalSection').textContent='Sección: '+b.dataset.requestLabel;m.hidden=false;m.style.display='flex'}));document.getElementById('capacityCancel').addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)close()})})();</script>

<div id="cohortRequestModal" hidden style="position:fixed;inset:0;background:#0009;z-index:9999;align-items:center;justify-content:center;padding:1rem" role="dialog" aria-modal="true" aria-labelledby="cohortModalTitle"><div class="card" style="width:min(100%,540px)"><h2 id="cohortModalTitle">Solicitar ampliación de cohorte</h2><p id="cohortModalLabel"></p><form method="post" action="<?=$u?>/admin/academico/cupos/solicitar-cohorte"><input type="hidden" name="_csrf" value="<?=$h(\App\Core\Csrf::token())?>"><input type="hidden" name="oferta_id" id="cohortOffer"><input type="hidden" name="nivel_id" id="cohortLevel"><input type="hidden" name="paralelo_id" id="cohortParallel"><label>Cupos adicionales<input type="number" name="cantidad" min="1" max="100" required></label><label>Justificación<textarea name="motivo" minlength="10" required></textarea></label><div style="display:flex;gap:.75rem"><button class="btn" type="button" id="cohortCancel">Cancelar</button><button class="btn" type="submit">Enviar solicitud</button></div></form></div></div>
<script>(function(){const m=document.getElementById('cohortRequestModal');const close=()=>{m.hidden=true;m.style.display='none'};document.querySelectorAll('[data-cohort-request]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('cohortOffer').value=b.dataset.offer;document.getElementById('cohortLevel').value=b.dataset.level;document.getElementById('cohortParallel').value=b.dataset.parallel;document.getElementById('cohortModalLabel').textContent=b.dataset.name;m.hidden=false;m.style.display='flex'}));document.getElementById('cohortCancel').addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)close()})})();</script>
